Translate the following GNU C++14 code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to translate:
<original_code>
#include <bits/stdc++.h>
#define ll long long
#define FOR(i, l, r) for (int i = l; i <= r; i++)
using namespace std;
const int P = 998244353, mod = 1e9 + 7, B = 1e6;
int m(ll d) { return (d % P + P) % P; }
ll n, cnt, s[7];
int ans;
vector<int> p[7];

void dfs0(int d, ll v) {
    cnt++;
    p[d].push_back(m(cnt - v));
    if (d < 6) FOR(i, 0, 9) dfs0(d + 1, v * 10 + i);
}

int calc(int id, int f) {
    int ps = lower_bound(p[id].begin(), p[id].end(), P - f) - p[id].begin();
    return ((ll)f * p[id].size() + s[id] - (ll)P * (p[id].size() - ps)) % mod;
}

void dfs1(int d, ll v) {
    if (v > n) return;
    if (d >= 1) {
        if (v * B > n / 10 && v * B + B - 1 <= n) {
            int t = 1;
            FOR(i, 0, 6) (ans += calc(i, m(cnt - v * t))) %= mod, t *= 10;
            FOR(i, 0, 6) cnt += p[i].size();
            return;
        }
        (ans += m(++cnt - v)) %= mod;
    }
    FOR(i, !d, 9) dfs1(d + 1, v * 10 + i);
}

int main() {
    scanf("%lld", &n);
    dfs0(0, 0);
    FOR(i, 0, 6) {
        sort(p[i].begin(), p[i].end());
        for (int j = 0; j < (int)p[i].size(); j++) s[i] += p[i][j];
    }
    cnt = 0;
    dfs1(0, 0);
    printf("%d\n", ans);
    return 0;
}
</original_code>
